const item = $input.first().json;
const b = item.body ?? item;
const ndvi = parseFloat(b.ndvi_mean ?? b.ndvi ?? 'NaN');
let luz = parseFloat(b.luz_umol);
if (Number.isNaN(luz) && !Number.isNaN(ndvi)) {
  luz = Math.min(2000, Math.max(0, ndvi * 2000));
}
const base = ($env.CASTUO_API_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const token = ($env.CASTUO_ROBOTICS_LAB_BEARER_TOKEN || $env.CASTUO_API_TOKEN || '').trim();
if (!token) throw new Error('CASTUO_ROBOTICS_LAB_BEARER_TOKEN o CASTUO_API_TOKEN requerido');
const payload = {
  humedad: Number(b.humedad ?? 65),
  ph: Number(b.ph ?? 5.8),
  ec: Number(b.ec ?? 1.2),
  luz_umol: Number.isNaN(luz) ? 1200 : luz,
};
const url = `${base}/api/robotics/lab/neuromorphic/hydroponics/infer`;
const res = await fetch(url, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${token}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify(payload),
});
const text = await res.text();
let data;
try { data = JSON.parse(text); } catch { data = { raw: text }; }
return [{ json: { http_status: res.status, infer: data, request: payload, url } }];
